"""Minimal Excel formula evaluator for the subset used in out/model.xlsx.

openpyxl writes formulas without cached results and LibreOffice is not
installed, so verification recomputes each formula cell from the workbook
itself: refs, ranges, + - * / ( ), and SUM/AVERAGE/NPV/IRR/PMT.
"""
from __future__ import annotations

import re

import numpy_financial as npf
import openpyxl

RANGE = re.compile(r"(?:('?)([A-Za-z_][\w ]*)\1!)?\$?([A-Z]{1,3})\$?(\d+)"
                   r":\$?([A-Z]{1,3})\$?(\d+)")
CELL = re.compile(r"(?:('?)([A-Za-z_][\w ]*)\1!)?\$?([A-Z]{1,3})\$?(\d+)")
FUNC = re.compile(r"\b(SUM|AVERAGE|NPV|IRR|PMT)\(")


def _flat(values):
    out = []
    for v in values:
        out.extend(_flat(v)) if isinstance(v, (list, tuple)) else out.append(v)
    return [v for v in out if isinstance(v, (int, float))]


def _sum(*a):
    return sum(_flat(a))


def _average(*a):
    nums = _flat(a)
    return sum(nums) / len(nums)


def _npv(rate, *a):
    return sum(v / (1 + rate) ** i for i, v in enumerate(_flat(a), start=1))


def _irr(*a):
    return float(npf.irr(_flat(a)))


def _pmt(rate, nper, pv, fv=0, when=0):
    return float(npf.pmt(rate, nper, pv, fv, when))


FUNCS = {"SUM": _sum, "AVERAGE": _average, "NPV": _npv, "IRR": _irr, "PMT": _pmt}


class Evaluator:
    """Evaluates any cell of a workbook, resolving formula dependencies."""

    def __init__(self, path):
        self.wb = openpyxl.load_workbook(path)
        self.cache: dict[tuple[str, str], object] = {}
        self.stack: list[tuple[str, str]] = []

    def cell(self, sheet: str, addr: str):
        key = (sheet, addr.replace("$", ""))
        if key in self.cache:
            return self.cache[key]
        if key in self.stack:
            raise ValueError(f"circular reference at {key}")
        self.stack.append(key)
        try:
            value = self.wb[key[0]][key[1]].value
            result = self._eval(value, key[0]) if isinstance(value, str) and \
                value.startswith("=") else (0 if value is None else value)
        finally:
            self.stack.pop()
        self.cache[key] = result
        return result

    def rng(self, sheet: str, start: str, end: str):
        cells = self.wb[sheet][f"{start}:{end}"]
        return [self.cell(sheet, c.coordinate) for row in cells for c in row]

    def _eval(self, formula: str, sheet: str):
        expr = FUNC.sub(lambda m: f"F['{m.group(1)}'](", formula[1:])
        expr = RANGE.sub(
            lambda m: f"*E.rng({m.group(2)!r} if {m.group(2)!r} else {sheet!r},"
                      f"{m.group(3) + m.group(4)!r},{m.group(5) + m.group(6)!r})",
            expr)
        expr = CELL.sub(
            lambda m: f"E.cell({m.group(2)!r} if {m.group(2)!r} else {sheet!r},"
                      f"{m.group(3) + m.group(4)!r})",
            expr)
        try:
            return eval(expr, {"E": self, "F": FUNCS, "__builtins__": {}})
        except Exception as exc:                       # pragma: no cover
            raise ValueError(f"cannot evaluate {formula!r} -> {expr!r}: {exc}") from exc

    def value(self, sheet: str, addr: str):
        return self.cell(sheet, addr)
PY
